-- Comentarios do CTN, lote 1 (arts. 1 a 20). Autorizados pela Jessica em 22/10/2026; redigidos so a partir do texto do artigo e dos filhos no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 1 and 20 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(1,'','Objeto e fundamento do CTN','A Lei regula, com fundamento na Emenda Constitucional n. 18, de 1965, o sistema tributário nacional e estabelece, com fundamento no art. 5º, inciso XV, alínea b, da Constituição Federal, as normas gerais de direito tributário aplicáveis à União, aos Estados, ao Distrito Federal e aos Municípios, sem prejuízo da respectiva legislação complementar, supletiva ou regulamentar.'),
(2,'','Fontes do sistema tributário nacional','O sistema tributário nacional é regido pela Emenda Constitucional n. 18, de 1965, por leis complementares, por resoluções do Senado Federal e, nos limites das respectivas competências, por leis federais, pelas Constituições e leis estaduais e pelas leis municipais.'),
(3,'','Conceito de tributo','Tributo é toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada. Os elementos do conceito são a prestação pecuniária, a compulsoriedade, a natureza não sancionatória, a instituição por lei e a cobrança por atividade administrativa plenamente vinculada.'),
(4,'','Natureza jurídica específica do tributo','A natureza jurídica específica do tributo é determinada pelo fato gerador da respectiva obrigação. São irrelevantes para qualificá-la a denominação e demais características formais adotadas pela lei (inciso I) e a destinação legal do produto da sua arrecadação (inciso II).'),
(5,'','Espécies de tributo','Os tributos são impostos, taxas e contribuições de melhoria, nos termos do artigo.'),
(6,'','Competência tributária e competência legislativa plena','A atribuição constitucional de competência tributária compreende a competência legislativa plena, ressalvadas as limitações contidas na Constituição Federal, nas Constituições dos Estados e nas Leis Orgânicas do Distrito Federal e dos Municípios, e observado o disposto no CTN. O parágrafo único dispõe que os tributos cuja receita seja distribuída, no todo ou em parte, a outras pessoas jurídicas de direito público pertencem à competência legislativa daquela a que tenham sido atribuídos.'),
(7,'','Indelegabilidade da competência tributária','A competência tributária é indelegável, salvo atribuição das funções de arrecadar ou fiscalizar tributos, ou de executar leis, serviços, atos ou decisões administrativas em matéria tributária, conferida por uma pessoa jurídica de direito público a outra, nos termos do § 3º do art. 18 da Constituição. O § 1º dispõe que a atribuição compreende as garantias e os privilégios processuais que competem à pessoa jurídica que a conferir. O § 2º dispõe que a atribuição pode ser revogada, a qualquer tempo, por ato unilateral da pessoa jurídica que a tenha conferido. O § 3º dispõe que não constitui delegação de competência o cometimento, a pessoas de direito privado, do encargo ou da função de arrecadar tributos.'),
(8,'','Não-exercício da competência tributária','O não-exercício da competência tributária não a defere a pessoa jurídica de direito público diversa daquela a que a Constituição a tenha atribuído.'),
(9,'','Vedações aos entes federativos','É vedado à União, aos Estados, ao Distrito Federal e aos Municípios: instituir ou majorar tributo sem que a lei o estabeleça, ressalvado, quanto à majoração, o disposto nos arts. 21, 26 e 65 (inciso I); cobrar imposto sobre o patrimônio e a renda com base em lei posterior à data inicial do exercício financeiro a que corresponda (inciso II); estabelecer limitações ao tráfego, no território nacional, de pessoas ou mercadorias, por meio de tributos interestaduais ou intermunicipais (inciso III); e cobrar impostos e a contribuição de que trata o inciso V do art. 195 da Constituição Federal sobre o patrimônio, a renda ou os serviços uns dos outros, entidades religiosas e templos de qualquer culto, patrimônio, renda ou serviços dos partidos políticos, das entidades sindicais dos trabalhadores, das instituições de educação e de assistência social sem fins lucrativos, e papel destinado exclusivamente à impressão de jornais, periódicos e livros (inciso IV, alíneas a a d). O § 1º dispõe que o inciso IV não exclui a atribuição, por lei, às entidades nele referidas, da condição de responsáveis pelos tributos que lhes caiba reter na fonte, e não as dispensa de atos assecuratórios do cumprimento de obrigações tributárias por terceiros. O § 2º dispõe que a alínea a do inciso IV aplica-se exclusivamente aos serviços próprios das pessoas jurídicas de direito público e inerentes aos seus objetivos.'),
(10,'','Uniformidade dos tributos da União','É vedado à União instituir tributo que não seja uniforme em todo o território nacional, ou que importe distinção ou preferência em favor de determinado Estado ou Município.'),
(11,'','Vedação de diferença tributária pela procedência ou destino','É vedado aos Estados, ao Distrito Federal e aos Municípios estabelecer diferença tributária entre bens de qualquer natureza, em razão da sua procedência ou do seu destino.'),
(12,'','Extensão da vedação às autarquias','O disposto na alínea a do inciso IV do art. 9º, observados os seus §§ 1º e 2º, é extensivo às autarquias criadas pela União, pelos Estados, pelo Distrito Federal ou pelos Municípios, tão-somente no que se refere ao patrimônio, à renda ou aos serviços vinculados às suas finalidades essenciais, ou delas decorrentes.'),
(13,'','Serviços públicos concedidos','O disposto na alínea a do inciso IV do art. 9º não se aplica aos serviços públicos concedidos, cujo tratamento tributário é estabelecido pelo poder concedente, no que se refere aos tributos de sua competência, ressalvado o parágrafo único. Este dispõe que, mediante lei especial e tendo em vista o interesse comum, a União pode instituir isenção de tributos federais, estaduais e municipais para os serviços públicos que conceder, observado o § 1º do art. 9º.'),
(14,'','Requisitos para a imunidade das entidades do art. 9º, IV, c','O disposto na alínea c do inciso IV do art. 9º é subordinado à observância de três requisitos pelas entidades nele referidas: não distribuírem qualquer parcela de seu patrimônio ou de suas rendas, a qualquer título (inciso I); aplicarem integralmente, no País, os seus recursos na manutenção dos seus objetivos institucionais (inciso II); e manterem escrituração de suas receitas e despesas em livros revestidos de formalidades capazes de assegurar sua exatidão (inciso III). O § 1º dispõe que, na falta de cumprimento do artigo ou do § 1º do art. 9º, a autoridade competente pode suspender a aplicação do benefício. O § 2º dispõe que os serviços a que se refere a alínea c do inciso IV do art. 9º são exclusivamente os diretamente relacionados com os objetivos institucionais das entidades, previstos nos respectivos estatutos ou atos constitutivos.'),
(15,'','Empréstimos compulsórios','Somente a União, nos casos excepcionais do artigo, pode instituir empréstimos compulsórios: guerra externa ou sua iminência (inciso I); calamidade pública que exija auxílio federal impossível de atender com os recursos orçamentários disponíveis (inciso II); e conjuntura que exija a absorção temporária de poder aquisitivo (inciso III). O parágrafo único dispõe que a lei fixará obrigatoriamente o prazo do empréstimo e as condições de seu resgate, observando, no que for aplicável, o disposto no CTN.'),
(16,'','Conceito de imposto','Imposto é o tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica, relativa ao contribuinte.'),
(17,'','Impostos do sistema tributário nacional','Os impostos componentes do sistema tributário nacional são exclusivamente os que constam do Título, com as competências e limitações nele previstas.'),
(18,'','Impostos nos Territórios e no Distrito Federal','Compete à União instituir, nos Territórios Federais, os impostos atribuídos aos Estados e, se aqueles não forem divididos em Municípios, cumulativamente, os atribuídos a estes (inciso I). Compete ao Distrito Federal e aos Estados não divididos em Municípios instituir, cumulativamente, os impostos atribuídos aos Estados e aos Municípios (inciso II).'),
(18,'Art. 18-A','Essencialidade de combustíveis, energia, comunicações e transporte coletivo','Para fins da incidência do imposto de que trata o inciso II do caput do art. 155 da Constituição Federal, os combustíveis, o gás natural, a energia elétrica, as comunicações e o transporte coletivo são considerados bens e serviços essenciais e indispensáveis, que não podem ser tratados como supérfluos. O parágrafo único, para efeito do artigo, veda a fixação de alíquotas sobre as operações referidas em patamar superior ao das operações em geral, considerada a essencialidade dos bens e serviços (inciso I), e facultada ao ente federativo competente a aplicação de alíquotas reduzidas em relação a esses bens, como forma de beneficiar os consumidores em geral (inciso II).'),
(19,'','Imposto de importação: fato gerador','O imposto, de competência da União, sobre a importação de produtos estrangeiros tem como fato gerador a entrada destes no território nacional.'),
(20,'','Imposto de importação: base de cálculo','A base de cálculo do imposto é, quando a alíquota seja específica, a unidade de medida adotada pela lei tributária (inciso I); quando a alíquota seja ad valorem, o preço normal que o produto, ou seu similar, alcançaria, ao tempo da importação, em uma venda em condições de livre concorrência, para entrega no porto ou lugar de entrada do produto no País (inciso II); e, quando se trate de produto apreendido ou abandonado, levado a leilão, o preço da arrematação (inciso III).')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
